shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,45 @@
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<char>());
+  struct test_case {
+    double value;
+    const char* expected;
+  };
+  const test_case cases[] = {{-119.921, "-119?921"},
+                             {2194.139, "2~194?139"},
+                             {-57.639, "-57?639"},
+                             {-5.980, "-5?980"},
+                             {-2.119, "-2?119"},
+                             {0.295, "0?295"},
+                             {1.295, "1?295"},
+                             {0.0, "0?000"},
+                             {-0.0, "-0?000"},
+                             {1234567.89, "1~234~567?890"}};
+  for (auto c : cases) {
+    auto expected = std::string(c.expected);
+    auto padding = std::string(19 - expected.size(), ' ');
+    EXPECT_EQ(padding + expected, fmt::format(loc, "{:19.3Lf}", c.value));
+    EXPECT_EQ(expected + padding, fmt::format(loc, "{:<19.3Lf}", c.value));
+  }
+  EXPECT_EQ("**1?295***", fmt::format(loc, "{:*^10.3Lf}", 1.295));
+  EXPECT_EQ("-00001?295", fmt::format(loc, "{:010.3Lf}", -1.295));
+  EXPECT_EQ("    1?234567", fmt::format(loc, "{:12L}", 1.234567));
+}
+
+TEST(locale_test, localized_wdouble_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
+  EXPECT_EQ(L"     0?295", fmt::format(loc, L"{:10.3Lf}", 0.295));
+  EXPECT_EQ(L"     1?295", fmt::format(loc, L"{:10.3Lf}", 1.295));
+  EXPECT_EQ(L"  -119?921", fmt::format(loc, L"{:10.3Lf}", -119.921));
+  EXPECT_EQ(L" 2~194?139", fmt::format(loc, L"{:10.3Lf}", 2194.139));
+  EXPECT_EQ(L"1?295     ", fmt::format(loc, L"{:<10.3Lf}", 1.295));
+  EXPECT_EQ(L"**1?295***", fmt::format(loc, L"{:*^10.3Lf}", 1.295));
+  EXPECT_EQ(L"-00001?295", fmt::format(loc, L"{:010.3Lf}", -1.295));
+  EXPECT_EQ(L"    1?234567", fmt::format(loc, L"{:12L}", 1.234567));
+}
+
 TEST(locale_test, format) {
PATCH
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized*alignment'

